from itertools import product
# Full Λ8 enumeration (from lam8)
def L8():
    out=[]
    for n in range(1,4):
      for l in range(0,min(1,n-1)+1):
        for k in range(1,min(3,4*l+2)+1):
          for q in range(0,k+1):
            for e in range(1,4):
              for f in range(0,min(1,e-1)+1):
                for g in range(0,min(4*f+2,q)+1):
                  for S2 in range(0,k+1):
                    out.append((n,l,k,q,e,f,g,S2))
    return out
cells=L8()
print('|Λ8| =', len(cells), '(expect 976)')
# coordinate order (n, ℓ, k, q, e, f, g, 2S)
# §7.4 caps: (n,e,ℓ,k,f) = (3,3,1,3,1)
idx={'n':0,'l':1,'k':2,'q':3,'e':4,'f':5,'g':6,'S2':7}
caps={}
for name,i in idx.items():
    caps[name]=max(c[i] for c in cells)
print('per-coordinate maxima:', caps)
print('caps (n,e,l,k,f) =', (caps['n'],caps['e'],caps['l'],caps['k'],caps['f']), '(expect (3,3,1,3,1))')
# box = product of (max+1) over the 8 coords? handoff says box 6,912 void 5,936 for the L8 space
box=1
for name,i in idx.items():
    box*= (caps[name]+1)
print('box (prod of (max+1) all 8):', box, '(expect 6,912)')
print('void = box - cells:', box-len(cells), '(expect 5,936)')
"

