# Λ₉ = L8 with 2S' appended, 2S' in 0..g (from lam8 L9: s in range(0, x[6]+1) where x[6]=g)
def L8():
    out=[]
    for n in range(1,4):
      for l in range(0,min(1,n-1)+1):
        for k in range(1,min(3,4*l+2)+1):
          for q in range(0,k+1):
            for e in range(1,4):
              for f in range(0,min(1,e-1)+1):
                for g in range(0,min(4*f+2,q)+1):
                  for S2 in range(0,k+1):
                    out.append((n,l,k,q,e,f,g,S2))
    return out
def L9():
    return [x+(s,) for x in L8() for s in range(0,x[6]+1)]
cells=L9()
print('|Λ9| =', len(cells), '(expect 1654)')
# Coordinates of a Λ9 cell: (n, l, k, q, e, f, g, 2S, 2S')  -- index 0..8
# Source signature = (n, l, k, 2S) = indices (0,1,2,7)
# Target signature = (e, f, g, 2S') = indices (4,5,6,8)
# Composition b∘a defined when a's TARGET == b's SOURCE.
# a target = (e_a, f_a, g_a, S2p_a) ; b source = (n_b, l_b, k_b, 2S_b)
# So match: (e_a, f_a, g_a, S2p_a) == (n_b, l_b, k_b, S2_b)
def src(c): return (c[0],c[1],c[2],c[7])
def tgt(c): return (c[4],c[5],c[6],c[8])
# Count composable pairs (a,b) with tgt(a)==src(b).
from collections import defaultdict
by_src=defaultdict(list)
for i,c in enumerate(cells):
    by_src[src(c)].append(i)
pairs=0
for a in cells:
    t=tgt(a)
    if t in by_src:
        pairs += len(by_src[t])
print('composable pairs (tgt(a)==src(b)):', pairs, '(expect 41,682)')
"

