                    out.append((n,l,k,q,e,f,g,S2))
    return out
def L9(): return [x+(s,) for x in L8() for s in range(0,x[6]+1)]

# --- Λ₈ composability on the book's own signature: source (n,l,k,2S)=4, target (e,f,g)=3 ---
# Text: four against three -> nothing composes. A cell composes if its target can be some cell's source.
# For Λ8, target=(e,f,g) 3-tuple, source=(n,l,k,2S) 4-tuple: shapes differ, so tgt can never equal a src. 0.
c8=L8()
# how many Λ8 cells are 'composable' = target matches some source? Different arity => 0.
print('Λ₈ composable: 0 by arity mismatch (4 vs 3) -> matches table 0/976')

# --- Λ₉ ---
c9=L9()
def src9(c): return (c[0],c[1],c[2],c[7])
def tgt9(c): return (c[4],c[5],c[6],c[8])
srcset=set(src9(c) for c in c9)
comp9=sum(1 for c in c9 if tgt9(c) in srcset)
print('Λ₉ composable cells (target is some source):', comp9, '/', len(c9), '=', round(comp9/len(c9),4), '(expect 1,169 / 0.7068)')
"

