def L11(): return \[c+(jc,) for c in L10() for jc in range(0, PHI\[c\[2\]\]+1)\]  
def L12(): return \[c+(K2,) for c in L11() for K2 in range(0, c\[10\]+2\*FMAX+1)\]  
def L13(): return \[c+(J2,) for c in L12() for J2 in range(max(0,c\[11\]-1), c\[11\]+2)\]  

